Y=(B+C)/2;
draw(X--Y, dashed);
draw(A--B--C--D--A);
draw(A--O--B);
draw(O--P, dashed);
label("A", A, NW);
label("B", B, NE);
label("C", C, SE);
label("D", D, SW);
label("O", O, S);
label("P", P, N);
